from taf.internal.scf.exceptions import ElementNotFound
from taf.internal.scf.scf import SCF as InternalSCF
from taf.internal.scf.p import P
from taf.internal.scf.list import List
from taf.internal.scf.managed_object import ManagedObject
from .model import DeltaJSON
from copy import deepcopy


class ThisSCF(InternalSCF):
    def has_managed_object(self, dist_name):
        return self.raml.cmData.child_exists(dist_name)

    def add_managed_object(self, managed_object):
        self.raml.cmData.append(managed_object)

    def get_managed_object(self, dist_name):
        return getattr(self.raml.cmData, dist_name)

    @property
    def managed_objects(self):
        return self.raml.cmData.get_all_descendant_mos()

    def add_parameter_to_managed_object(self, managed_object, param):
        managed_object.append(param)


class ScfCalculator(object):
    """
    Calculate delta scf.
    """

    @staticmethod
    def calculate_delta(target_scf, actual_scf):
        """ creates a scf file which can be used to revert the difference between target scf and actual scf

        :param InternalSCF target_scf: target scf
        :param InternalSCF actual_scf: actual scf

        :return: InternalSCF delta_scf: output created delta scf
        """
        delta_scf = ThisSCF()

        target_mos = {mo.dist_name: mo for mo in target_scf.managed_objects}
        actual_mos = {mo.dist_name: mo for mo in actual_scf.managed_objects}

        for dist_name, mo in target_mos.items():
            if dist_name in actual_mos:
                ScfCalculator._check_children_of_mo_in_target_scf(mo, actual_scf, target_scf, delta_scf)
            else:
                delta_scf.add_managed_object(mo)

        for dist_name, mo in actual_mos.items():
            if dist_name not in target_mos:
                delete_mo = ManagedObject().create(klass=mo._tree.attrib['class'], dist_name=mo.dist_name,
                                                   operation="delete", version=mo._tree.attrib['version'])
                delta_scf.add_managed_object(delete_mo)

        delta_scf.raml.cmData["scope"] = "changes"
        delta_scf.raml.cmData["type"] = "plan"
        return delta_scf

    @staticmethod
    def _check_children_of_mo_in_target_scf(mo, actual_scf, target_scf, delta_scf):
        mo_in_target_scf = target_scf.get_managed_object(mo.dist_name)
        mo_in_actual_scf = actual_scf.get_managed_object(mo.dist_name)
        children_in_target_scf = {child._tree.get("name"): child for child in mo_in_target_scf}
        children_in_actual_scf = {child._tree.get("name"): child for child in mo_in_actual_scf}

        for child_name, child_in_mo_in_target_scf in children_in_target_scf.items():
            child_in_mo_in_actual_scf = children_in_actual_scf.get(child_name)
            if child_in_mo_in_actual_scf is None or repr(child_in_mo_in_actual_scf) != repr(child_in_mo_in_target_scf):
                ScfCalculator._update_delta_object_to_target_value(mo, child_in_mo_in_target_scf, target_scf, delta_scf)

        for child_name, child_in_mo_in_actual_scf in children_in_actual_scf.items():
            if child_name not in children_in_target_scf:
                ScfCalculator._update_delta_object_to_target_value(mo, child_in_mo_in_actual_scf, target_scf, delta_scf)

    @staticmethod
    def _update_delta_object_to_target_value(mo, child, target_scf, delta_scf):
        # update to target value
        child_name = child._tree.get("name")
        if not delta_scf.has_managed_object(mo.dist_name):
            update_mo = ManagedObject().create(klass=mo._tree.attrib['class'], dist_name=mo.dist_name,
                                               operation="update", version=mo._tree.attrib['version'])
            delta_scf.add_managed_object(update_mo)

        mo_in_delta_scf = delta_scf.get_managed_object(mo.dist_name)
        try:
            mo_in_target_scf = target_scf.get_managed_object(mo.dist_name)
            child_in_mo_in_target_scf = getattr(mo_in_target_scf, child_name)
        except ElementNotFound:
            if isinstance(child, List):
                # remove list found in actual scf and not found in target scf
                xlist = List().create(name=child_name)
                delta_scf.add_parameter_to_managed_object(mo_in_delta_scf, xlist)
            elif isinstance(child, P):
                # remove attribute found in actual scf and not found in target scf by setting it to empty value
                p = P().create(name=child_name, value="")
                delta_scf.add_parameter_to_managed_object(mo_in_delta_scf, p)
        else:
            delta_scf.add_parameter_to_managed_object(mo_in_delta_scf, deepcopy(child_in_mo_in_target_scf))


class MegazoneScfCalculator(object):
    @staticmethod
    def calculate_delta_scf(target_scf_path, actual_scf_path, delta_scf_path):
        """ creates a scf file which can be used to revert the difference between target scf and actual scf

        :param str target_scf_path: path where target configuration scf can be found
        :param str actual_scf_path: path where actual scf can be found
        :param str delta_scf_path: path to place where delta scf is to be created
        """
        target_scf = ThisSCF(target_scf_path)
        actual_scf = ThisSCF(actual_scf_path)
        delta_scf = ScfCalculator.calculate_delta(target_scf, actual_scf)
        delta_scf.save(delta_scf_path)


class CoamScfCalculator(object):

    @staticmethod
    def calculate_delta_scf(target_scf_path, actual_scf_path, delta_scf_path):
        """ creates a scf file which can be used to revert the difference between target scf and actual scf

        :param str target_scf_path: path where target configuration scf can be found
        :param str actual_scf_path: path where actual scf can be found
        :param str delta_scf_path: path to place where delta scf is to be created
        """
        target_scf = ThisSCF(target_scf_path)
        actual_scf = ThisSCF(actual_scf_path)
        delta_scf = ScfCalculator.calculate_delta(target_scf, actual_scf)
        delta_scf_json = CoamScfCalculator._convert_delta_scf_xml_to_json(delta_scf)
        with open(delta_scf_path, 'w') as delta_json:
            delta_json.write(delta_scf_json.serialize())

    @staticmethod
    def _convert_delta_scf_xml_to_json(delta_scf):
        delta_scf_json = DeltaJSON()
        for mo in delta_scf.raml.cmData.get_all_descendant_mos():
            operation = mo._tree.get("operation")
            delta_scf_json.append_managed_object(mo.dist_name, operation=operation)
            mo_in_delta_scf = getattr(delta_scf.raml.cmData, mo.dist_name)
            for child in mo_in_delta_scf:
                CoamScfCalculator._handle_childs(child, delta_scf_json, mo, mo_in_delta_scf)
        return delta_scf_json

    @staticmethod
    def _handle_childs(child, delta_scf_json, mo, mo_in_delta_scf):
        child_name = child._tree.get("name")
        child_in_mo_in_delta_scf = getattr(mo_in_delta_scf, child_name)
        if isinstance(child, P):
            value = child._tree.text
            if not value:  # to be deleted parameter
                delta_scf_json.append_parameter_delete(mo.dist_name, child_name)
            else:
                delta_scf_json.append_parameter_update(mo.dist_name, child_name, value)
        elif isinstance(child, List):
            if len(child_in_mo_in_delta_scf) == 0:  # to be deleted list
                delta_scf_json.append_parameter_delete(mo.dist_name, child_name)
            else:
                for item in child_in_mo_in_delta_scf:
                    CoamScfCalculator._handle_items(child_name, delta_scf_json, item, mo)

    @staticmethod
    def _handle_items(child_name, delta_scf_json, item, mo):
        if isinstance(item, P):
            value = item._tree.text
            delta_scf_json.append_list_items(mo.dist_name, child_name, value)
        else:  # instance is a List
            item_params = {}
            for p in item:
                p_name = p._tree.get("name")
                value = p._tree.text
                item_params.update({p_name: value})
            # could be done inside loop, but then there are too many parenthesis
            # inside the loop: delta_scf_json.append_complex_item(mo.dist_name, child_name, **{p_name: value})
            delta_scf_json.append_complex_item(mo.dist_name, child_name, **item_params)
